const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
let wins = 0;
for (const result of input) {
  if (result === 'V') wins++;
}

if (wins >= 5) {
  console.log(1);
} else if (wins >= 3) {
  console.log(2);
} else if (wins >= 1) {
  console.log(3);
} else {
  console.log(-1);
}
